  ('law-657-section-disiplin', 'general-legislation', 'law-657', 'section', 'Disiplin Cezaları ve Soruşturma', NULL, 'Madde 124 – 136', NULL, NULL, ARRAY[]::text[], 13, NULL, NULL, ARRAY[]::text[], true),
  ('law-222-section-ek-ge-ici-ve-son-h-k-mler', 'meb-legislation', 'law-222', 'section', 'Ek, Geçici ve Son Hükümler', NULL, 'Ek ve Geçici Maddeler', NULL, NULL, ARRAY[]::text[], 14, NULL, NULL, ARRAY[]::text[], true),
  ('law-657-section-gorevden-uzaklastirma', 'general-legislation', 'law-657', 'section', 'Görevden Uzaklaştırma', NULL, 'Madde 137 – 145', NULL, NULL, ARRAY[]::text[], 14, NULL, NULL, ARRAY[]::text[], true),
  ('law-657-section-mali-hukumler', 'general-legislation', 'law-657', 'section', 'Mali Hükümler (Aylık ve Ödenekler)', NULL, 'Madde 146 – 186', NULL, NULL, ARRAY[]::text[], 15, NULL, NULL, ARRAY[]::text[], true),
  ('law-657-section-sosyal-haklar-yardimlar', 'general-legislation', 'law-657', 'section', 'Sosyal Haklar ve Yardımlar', NULL, 'Madde 187 – 213', NULL, NULL, ARRAY[]::text[], 16, NULL, NULL, ARRAY[]::text[], true),
  ('law-657-section-memur-yetistirilmesi', 'general-legislation', 'law-657', 'section', 'Devlet Memurlarının Yetiştirilmesi', NULL, 'Madde 214 – 225', NULL, NULL, ARRAY[]::text[], 17, NULL, NULL, ARRAY[]::text[], true),
