  ('law-657-section-gecici-ve-son-hukumler', 'general-legislation', 'law-657', 'section', 'Geçici ve Son Hükümler', NULL, 'Ek/Geçici Maddeler, Madde 237 – 239', NULL, NULL, ARRAY[]::text[], 19, NULL, NULL, ARRAY[]::text[], true)
insert into public.questions (id, topic_id, prompt, options, answer_index, explanation, sort_order) values
  ('652-khk-cld652-000-hu66', '652-khk', '652 sayılı Kanun Hükmünde Kararname tarihsel olarak hangi amaçla çıkarılmıştır?', '["Sadece ders kitaplarının basımını düzenlemek","Sadece öğretmen maaşlarını düzenlemek","Sadece merkezi sınav sistemini düzenlemek","Sadece özel okulların denetimini düzenlemek","Millî Eğitim Bakanlığının teşkilat ve görevlerini düzenlemek"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Millî Eğitim Bakanlığının teşkilat ve görevlerini düzenlemek. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. 652 sayılı KHK''nin ilk hâlinin adı ''Millî Eğitim Bakanlığının Teşkilat ve Görevleri Hakkında Kanun Hükmünde Kararname'' idi; 2/7/2018 tarihli ve 703 sayılı KHK''nin 22 nci maddesiyle KHK''nin adı ve büyük bölümü değiştirilerek bugünkü hâlini almıştır.', 0),
  ('652-khk-cld652-002-952p', '652-khk', '652 sayılı KHK hangi yetki kanununa dayanılarak çıkarılmıştır?', '["5442 sayılı İl İdaresi Kanunu","657 sayılı Devlet Memurları Kanunu","1739 sayılı Millî Eğitim Temel Kanunu","6223 sayılı Yetki Kanunu","4982 sayılı Bilgi Edinme Hakkı Kanunu"]'::jsonb, 3, '[652 Sayılı KHK] Doğru cevap: 6223 sayılı Yetki Kanunu. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. 652 sayılı KHK''nin dayanağı, 6/4/2011 tarihli ve 6223 sayılı Yetki Kanunu''dur; KHK''nin kendisi 25/8/2011 tarihinde çıkarılmış, 14/9/2011 tarihli ve 28054 sayılı Resmî Gazete''de yayımlanmıştır.', 2),
  ('652-khk-cld652-003-afhs', '652-khk', '652 sayılı KHK''nin madde 1''den 12''ye, 14''ten 22''ye, 24''ten 30''a, 32''den 36''ya, 38''den 41''e kadar olan hükümleri ile 44 üncü maddesi, Ek Madde 1-4 ve 6, Geçici Madde 1-15 hangi düzenlemeyle yürürlükten kaldırılmıştır?', '["11/10/2011 tarihli ve 666 sayılı Kanun Hükmünde Kararname","1/3/2014 tarihli ve 6528 sayılı Kanun","2/12/2016 tarihli ve 6764 sayılı Kanun","10/10/2024 tarihli ve 7528 sayılı Kanun","2/7/2018 tarihli ve 703 sayılı Kanun Hükmünde Kararname"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: 2/7/2018 tarihli ve 703 sayılı Kanun Hükmünde Kararname. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. 703 sayılı KHK''nin 22 nci maddesi, 652 sayılı KHK''nin Bakanlık teşkilatına ilişkin neredeyse tüm hükümlerini (madde 1-12, 13''ün eski hâli, 14-22, 23''ün 1 inci fıkrası, 24-30, 31''in 1-4 üncü fıkraları, 32-36, 37''nin 1-2 ve 8-11 inci fıkraları [37/7 hariç], 38-41, 44, Ek Madde 1''in 1-2 ve 4 üncü fıkraları, Ek Madde 2-4, Ek Madde 6, Geçici Madde 1-15 ve (I) Sayılı Cetvel) yürürlükten kaldırmıştır.', 3),
  ('652-khk-cld652-007-evf9', '652-khk', 'Öğrencilere özel barınma hizmeti veren kurumlara, ortaokul ve ortaöğrenim düzeyinde kurum açma izni ile iş yeri açma ve çalışma ruhsatını hangi kurum verir?', '["Aile ve Sosyal Hizmetler Bakanlığı","Millî Eğitim Bakanlığı","Gençlik ve Spor Bakanlığı","Büyükşehir Belediyesi","İl Özel İdaresi"]'::jsonb, 1, '[652 Sayılı KHK] Doğru cevap: Millî Eğitim Bakanlığı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 13''e göre öğrencilere özel barınma hizmeti veren kurumlara kurum açma izni ile iş yeri açma ve çalışma ruhsatı, ortaokul ve ortaöğrenim düzeyinde Millî Eğitim Bakanlığınca, yükseköğrenim düzeyinde Gençlik ve Spor Bakanlığınca verilir.', 7),
  ('652-khk-cld652-008-8ss3', '652-khk', 'Öğrencilere özel barınma hizmeti veren kurumlara, yükseköğrenim düzeyinde kurum açma izni ile iş yeri açma ve çalışma ruhsatını hangi kurum verir?', '["Valilik","Kredi ve Yurtlar Kurumu","Gençlik ve Spor Bakanlığı","Yükseköğretim Kurulu","Millî Eğitim Bakanlığı"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Gençlik ve Spor Bakanlığı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 13''e göre yükseköğrenim düzeyindeki öğrencilere özel barınma hizmeti veren kurumlara ilişkin izin ve ruhsat yetkisi Gençlik ve Spor Bakanlığındadır; Millî Eğitim Bakanlığı bu yetkiyi ortaokul ve ortaöğrenim düzeyinde kullanır.', 8),
  ('652-khk-cld652-009-jtbx', '652-khk', 'Madde 13''e göre Millî Eğitim Bakanlığı ve Gençlik ve Spor Bakanlığı, özel barınma hizmeti veren kurumlara ilişkin izin ve ruhsat verme yetkilerini kime devredebilir?', '["Büyükşehir Belediyesi Başkanlıklarına","Belediyelere","Kaymakamlıklara","Valiliklere","İl Özel İdarelerine"]'::jsonb, 3, '[652 Sayılı KHK] Doğru cevap: Valiliklere. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 13''ün son fıkrasına göre bakanlıklar, özel barınma hizmeti veren kurumlara ilişkin izin ve ruhsat verme yetkilerini valiliklere devredebilir.', 9),
  ('652-khk-cld652-011-z95h', '652-khk', 'Madde 13''ün uygulanmasına ilişkin usul ve esaslar hangi düzenleyici işlemle belirlenir?', '["Tebliğ","Kanun","Genelge","Yönetmelik","Cumhurbaşkanlığı Kararnamesi"]'::jsonb, 3, '[652 Sayılı KHK] Doğru cevap: Yönetmelik. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 13''ün son cümlesine göre fıkranın uygulanmasına ilişkin usul ve esaslar yönetmelikle belirlenir.', 11),
  ('652-khk-cld652-012-165z', '652-khk', 'Madde 13''ün 2/7/2018 tarihli ve 703 sayılı KHK ile değiştirilen hâli, Anayasa Mahkemesinin hangi tarihli kararıyla iptal edilmiştir?', '["7/12/2023 tarihli ve E:2018/117, K:2023/212 sayılı Kararı","27/12/2012 tarihli ve E:2011/139, K:2012/205 sayılı Kararı","13/7/2015 tarihli ve E:2014/88, K:2015/68 sayılı Kararı","6/2/2013 tarihli ve E:2011/123, K:2013/26 sayılı Kararı","28/9/2023 tarihli ve E:2023/59, K:2023/164 sayılı Kararı"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: 7/12/2023 tarihli ve E:2018/117, K:2023/212 sayılı Kararı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 13''ün 703 sayılı KHK ile değiştirilen hâli, Anayasa Mahkemesinin 7/12/2023 tarihli ve E:2018/117, K:2023/212 sayılı Kararı ile iptal edilmiş; madde daha sonra 7551 sayılı Kanunla başlığıyla birlikte yeniden düzenlenmiştir.', 12),
  ('652-khk-cld652-013-7q04', '652-khk', 'Madde 13''ü başlığıyla birlikte yeniden düzenleyen 7551 sayılı Kanunun ilgili maddesi hangisidir ve bu düzenleme ne zaman yürürlüğe girmiştir?', '["7528 sayılı Kanunun 36 ncı maddesi; 18/10/2024 tarihinde yürürlüğe girmiştir","7551 sayılı Kanunun 27 nci maddesi; 1/7/2025 tarihinde yürürlüğe girmiştir","7180 sayılı Kanunun 18 inci maddesi; 5/7/2019 tarihinde yürürlüğe girmiştir","7551 sayılı Kanunun 13 üncü maddesi; 18/6/2025 tarihinde yürürlüğe girmiştir","703 sayılı KHK''nin 22 nci maddesi; 9/7/2018 tarihinde yürürlüğe girmiştir"]'::jsonb, 1, '[652 Sayılı KHK] Doğru cevap: 7551 sayılı Kanunun 27 nci maddesi; 1/7/2025 tarihinde yürürlüğe girmiştir. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 13, 18/6/2025 tarihli ve 7551 sayılı Kanunun 27 nci maddesiyle başlığıyla birlikte yeniden düzenlenmiş; değişiklik tablosuna göre bu düzenleme 1/7/2025 tarihinde yürürlüğe girmiştir.', 13),
  ('652-khk-cld652-014-67bo', '652-khk', '652 sayılı KHK''nin 23 üncü maddesinin başlığı nedir?', '["Sınav ücretleri","Atama","Taşra teşkilatı","Özel eğitim giderleri","İnşaat ve emlak işleri"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: İnşaat ve emlak işleri. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 23''ün başlığı ''İnşaat ve emlak işleri''dir; maddenin birinci fıkrası 703 sayılı KHK ile mülga edilmiş, ikinci ile altıncı fıkraları yürürlüktedir.', 14),
  ('652-khk-cld652-016-14j4', '652-khk', 'Madde 23/3-a hükmüne göre, yapılması gerekli görülen eğitim öğretim tesisleri, ihale ile belirlenecek gerçek veya özel hukuk tüzel kişilerine en fazla kaç yıl için kiralama karşılığı yaptırılabilir?', '["Elli yıl","On yıl","Kırk dokuz yıl","Yirmi beş yıl","Otuz yıl"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Kırk dokuz yıl. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 23/3-a''ya göre yapılmasının gerekli olduğuna Bakanlıkça karar verilen eğitim öğretim tesisleri, kendisine veya Hazineye ait taşınmazlar üzerinde ihale ile belirlenecek gerçek veya özel hukuk tüzel kişilerine kırk dokuz yılı geçmemek şartıyla belirli süre ve bedel üzerinden kiralama karşılığı yaptırılabilir.', 16),
  ('652-khk-cld652-017-oh34', '652-khk', 'Madde 23/3-b''ye göre bedelsiz devredilen Hazineye ait taşınmazların sözleşme süresince amacı dışında kullanılamayacağına ve ilgili bakanlıklardan izin alınmaksızın devredilemeyeceğine dair ne konulur?', '["Tapu kütüğüne şerh","İntifa hakkı","Kamulaştırma şerhi","İpotek","Haciz"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: Tapu kütüğüne şerh. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 23/3-b''ye göre bu taşınmazların sözleşme süresince amacı dışında kullanılamayacağına, Hazine ve Maliye ile Millî Eğitim Bakanlıklarından izin alınmaksızın devredilemeyeceğine dair tapu kütüğüne şerh konulur.', 17),
  ('652-khk-cld652-018-8q9z', '652-khk', 'Madde 23/3-c''ye göre kira bedeli ve kiralama süresinin tespitinde aşağıdakilerden hangisi dikkate alınan hususlardan biri değildir?', '["Yatırımın maliyeti","Eğitim öğretim donanımının bu kişiler tarafından sağlanıp sağlanmayacağı","Bedelsiz Hazine taşınmazı devredilip devredilmediği","Taşınmazın gerçek veya özel hukuk tüzel kişilerine ait olup olmadığı","Kiracının vergi mükellefiyet süresi"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Kiracının vergi mükellefiyet süresi. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 23/3-c''ye göre kira bedeli ve kiralama süresinin tespitinde taşınmazın mülkiyet durumu, bedelsiz devir olup olmadığı, yatırım maliyeti, donanımın sağlanma şekli ve eğitim öğretim hizmetleri dışındaki alanların işletilmesinin kiralayana verilip verilmeyeceği dikkate alınır; kiracının vergi mükellefiyet süresi madde metninde yer almaz.', 18),
  ('652-khk-cld652-020-z1ms', '652-khk', 'Madde 23/5''e göre birinci fıkra hariç bu maddeye göre yapılacak iş ve işlemler hangi kanunlara tabi değildir?', '["2886 sayılı Devlet İhale Kanunu ile 4734 sayılı Kamu İhale Kanunu","5580 sayılı Kanun ile 4688 sayılı Kanun","657 sayılı Devlet Memurları Kanunu ile 5442 sayılı Kanun","4735 sayılı Kamu İhale Sözleşmeleri Kanunu ile 5018 sayılı Kanun","222 sayılı Kanun ile 1739 sayılı Kanun"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: 2886 sayılı Devlet İhale Kanunu ile 4734 sayılı Kamu İhale Kanunu. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 23/5''e göre birinci fıkra hariç bu maddeye göre yapılacak iş ve işlemler, 2886 sayılı Devlet İhale Kanunu ile 4734 sayılı Kamu İhale Kanununa tabi değildir.', 20),
  ('652-khk-cld652-022-375x', '652-khk', '652 sayılı KHK''nin 31 inci maddesinin yürürlükte kalan tek fıkrası hangisidir?', '["Birinci fıkra","Dördüncü fıkra","Beşinci fıkra","İkinci fıkra","Üçüncü fıkra"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Beşinci fıkra. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 31''in 1 ila 4 üncü fıkraları 2/7/2018 tarihli ve 703 sayılı KHK ile mülga edilmiştir; yalnızca 1/3/2014 tarihli ve 6528 sayılı Kanunun 21 inci maddesiyle eklenen 5 inci fıkra yürürlüktedir.', 22),
  ('652-khk-cld652-023-mq53', '652-khk', 'Madde 31/5''e göre mahallinden sözleşmeli statüde öğretmen olarak istihdam edilebilmek için, ilgili ülke vatandaşlığına sahip olanların yanı sıra hangi şart da aranır?', '["KPSS''ye girmiş olması","Türkiye Cumhuriyeti vatandaşı olması","Süresiz oturma ve çalışma izni bulunması","En az 5 yıl öğretmenlik deneyimi olması","Yüksek lisans derecesine sahip olması"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Süresiz oturma ve çalışma izni bulunması. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 31/5''e göre Türkiye''deki veya YÖK tarafından denkliği kabul edilen yurt dışındaki üniversitelerin ilgili bölümlerinden lisans düzeyinde eğitimini başarıyla bitirenlerden ilgili ülke vatandaşlığına sahip olanlarla süresiz oturma ve çalışma izni bulunanlar bu kapsamda istihdam edilebilir.', 23),
  ('652-khk-cld652-029-gm0j', '652-khk', 'Madde 37/7, hangi kanunla değişik hâlini almıştır?', '["10/10/2024 tarihli ve 7528 sayılı Kanun","1/3/2014 tarihli ve 6528 sayılı Kanun","12/7/2012 tarihli ve 6353 sayılı Kanun","9/12/2016 tarihli ve 6764 sayılı Kanun","2/7/2018 tarihli ve 703 sayılı KHK"]'::jsonb, 1, '[652 Sayılı KHK] Doğru cevap: 1/3/2014 tarihli ve 6528 sayılı Kanun. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 37/7, 1/3/2014 tarihli ve 6528 sayılı Kanunun 22 nci maddesiyle değişik hâlini almış, daha sonra 7528 sayılı Kanunla bazı unvanlar madde metninden çıkarılmıştır.', 29),
  ('652-khk-cld652-030-2afa', '652-khk', 'Madde 43/1''e göre erişkin bireylerde destek eğitimi giderlerinin karşılanabilmesi için asgari hangi oranda engelli olunduğunun tespit edilmesi gerekir?', '["%20","%10","%40","%70","%50"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: %20. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 43/1''e göre Erişkinler İçin Engellilik Sağlık Kurulu Raporuyla asgari %20 oranında engelli olduğu tespit edilenler, şartları taşımaları hâlinde destek eğitiminden yararlanabilir.', 30),
  ('652-khk-cld652-031-28fm', '652-khk', 'Madde 43/1''e göre 18 yaş altı çocuklarda özel gereksinim tespiti hangi raporla yapılır?', '["Erişkinler İçin Engellilik Sağlık Kurulu Raporu","Çocuklar İçin Özel Gereksinim Raporu","Engelli Sağlık Kurulu Raporu","Sağlık Kurulu Raporu","Özel Eğitim Değerlendirme Raporu"]'::jsonb, 1, '[652 Sayılı KHK] Doğru cevap: Çocuklar İçin Özel Gereksinim Raporu. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 43/1''e göre 18 yaş altı çocukların Çocuklar İçin Özel Gereksinim Raporu ile özel gereksinimi olduğu tespit edilmesi ve özel eğitim değerlendirme kurullarınca eğitsel değerlendirme ve tanılamalarının yapılması gerekir.', 31),
  ('652-khk-cld652-033-rwja', '652-khk', 'Madde 43/1''e göre destek eğitimi kapsamındaki bireylerin eğitim giderlerinin tutarını hangi kurum belirler?', '["Sağlık Bakanlığı","Cumhurbaşkanlığı","Millî Eğitim Bakanlığı","Aile ve Sosyal Hizmetler Bakanlığı","Hazine ve Maliye Bakanlığı"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Hazine ve Maliye Bakanlığı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 43/1''e göre eğitim giderlerinin her yıl Hazine ve Maliye Bakanlığınca belirlenen tutarı, Bakanlık bütçesine bu amaçla konulan ödenekten karşılanır.', 33),
  ('652-khk-cld652-036-sf0k', '652-khk', 'Madde 43/2''ye göre gerçek dışı beyan fiilinin özel eğitim okulları ile özel eğitim ve rehabilitasyon merkezleri tarafından tekrarı hâlinde ayrıca ne yapılır?', '["Sorumlu personel görevden alınır","Faaliyetleri bir yıl süreyle askıya alınır","Kurum açma izinleri iptal edilir","Sadece para cezası uygulanır","Sadece uyarı verilir"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Kurum açma izinleri iptal edilir. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 43/2''nin son cümlesine göre bu fiillerin özel eğitim okulları ile özel eğitim ve rehabilitasyon merkezleri tarafından tekrarı hâlinde, ayrıca kurum açma izinleri iptal edilir.', 36),
  ('652-khk-cld652-037-it60', '652-khk', 'Madde 43/3''e göre engelli bireylerin özel eğitim ve rehabilitasyon merkezlerine kayıt-kabul işlemleri ile ders devam takibi hangi tarihten itibaren biyometrik kimlik doğrulama veya kameralı görüntüleme sistemiyle yapılır?', '["1/9/2019","1/1/2018","1/9/2017","1/9/2018","1/9/2016"]'::jsonb, 3, '[652 Sayılı KHK] Doğru cevap: 1/9/2018. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 43/3''e göre bu işlemler 1/9/2018 tarihinden itibaren biyometrik kimlik doğrulama sistemi veya kameralı görüntüleme sistemi ile yapılır.', 37),
  ('652-khk-cld652-039-yagy', '652-khk', 'Madde 43''ün 1 inci fıkrasında yer alan ''Maliye Bakanlığınca'' ibaresi, 2/7/2018 tarihli ve 703 sayılı KHK''nin 22 nci maddesiyle nasıl değiştirilmiştir?', '["''Bakanlar Kurulunca'' şeklinde","''Aile ve Sosyal Hizmetler Bakanlığınca'' şeklinde","''Hazine ve Maliye Bakanlığınca'' şeklinde","''Cumhurbaşkanlığınca'' şeklinde","''Millî Eğitim Bakanlığınca'' şeklinde"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: ''Hazine ve Maliye Bakanlığınca'' şeklinde. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 43 dipnotuna göre 703 sayılı KHK''nin 22 nci maddesiyle bu maddenin birinci fıkrasında yer alan ''Maliye Bakanlığınca'' ibaresi ''Hazine ve Maliye Bakanlığınca'' şeklinde ve ''Aile ve Sosyal Politikalar Bakanlığının'' ibaresi ''Çalışma, Sosyal Hizmetler ve Aile Bakanlığının'' şeklinde değiştirilmiştir.', 39),
  ('652-khk-cld652-040-edww', '652-khk', '652 sayılı KHK''nin Ek Madde 1''inin yürürlükte kalan tek fıkrası hangisidir?', '["İkinci fıkra","Birinci fıkra","Dördüncü fıkra","Üçüncü fıkra","Beşinci fıkra"]'::jsonb, 3, '[652 Sayılı KHK] Doğru cevap: Üçüncü fıkra. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 1''in 1, 2 ve 4 üncü fıkraları 2/7/2018 tarihli ve 703 sayılı KHK ile mülga edilmiş; yalnızca 3 üncü fıkra yürürlüktedir.', 40),
  ('652-khk-cld652-041-bb64', '652-khk', 'Ek Madde 1/3''e göre Bakanlıkça yapılan merkezi sınavlarda görev yapan bina sınav sorumluları, sınav koordinatörü, gözetmenler ve sınav güvenliğini sağlayan kolluk kuvvetlerine hangi hesaptan ödeme yapılır?', '["Bakanlık merkez teşkilatı ödeneğinden","İl özel idaresi bütçesinden","Sınav ücretinden kesinti yapılarak","Genel bütçeden doğrudan","Döner sermaye hesabından"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Döner sermaye hesabından. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 1/3''e göre merkezi sınavlarda görev alan personele (bina sınav sorumluları, sınav koordinatörü ve yardımcıları, bina yöneticileri, salon başkanları, gözetmenler, kolluk kuvvetleri, soru hazırlayanlar, diğer görevliler) döner sermaye hesabından sınav veya soru ücreti ödenir.', 41),
  ('652-khk-cld652-042-ut2u', '652-khk', 'Ek Madde 1/3''e göre Bakanlık merkez teşkilatında kadrolu veya sözleşmeli çalışan personele, sınav sorularının hazırlanmasına katkıları sebebiyle ayrıca soru ücreti ödenir mi?', '["Hayır, ayrıca soru ücreti ödenmez","Evet ama yarım ücret ödenir","Sadece yöneticilere ödenir","Evet, çift ücret ödenir","Sadece yıl sonunda toplu olarak ödenir"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: Hayır, ayrıca soru ücreti ödenmez. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 1/3''ün ikinci cümlesine göre Bakanlık merkez teşkilatında kadrolu veya sözleşmeli çalışan personele sınav sorularının hazırlanmasına katkıları sebebiyle ayrıca soru ücreti ödenmez.', 42),
  ('652-khk-cld652-043-h53k', '652-khk', 'Ek Madde 1/3''e göre memuriyet mahalli dışına sınav görevi için görevlendirilenlere, sınav ücreti dışında hangi kanuna göre sadece yol gideri ödenir?', '["6245 sayılı Harcırah Kanunu","4734 sayılı Kamu İhale Kanunu","5018 sayılı Kamu Malî Yönetimi ve Kontrol Kanunu","375 sayılı Kanun Hükmünde Kararname","657 sayılı Devlet Memurları Kanunu"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: 6245 sayılı Harcırah Kanunu. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 1/3''e göre memuriyet mahalli dışına sınav görevi için görevlendirilenlere sınav ücreti dışında 10/2/1954 tarihli ve 6245 sayılı Harcırah Kanunu hükümlerine göre sadece yol gideri ödenir.', 43),
  ('652-khk-cld652-044-j7n1', '652-khk', 'Ek Madde 1/3''e göre sınav ücretinin tutarı ile usul ve esasları hangi makam tarafından tespit edilir?', '["Cumhurbaşkanı","Ölçme, Değerlendirme ve Sınav Hizmetleri Genel Müdürü","Millî Eğitim Bakanı","Hazine ve Maliye Bakanı","Bakanlar Kurulu"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: Cumhurbaşkanı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 1/3''ün son cümlesine göre sınav ücretinin tutarı ile usul ve esasları Cumhurbaşkanınca tespit edilir. (2/7/2018 tarihli ve 703 sayılı KHK ile bu yetki ''Bakanlar Kurulu kararı''ndan ''Cumhurbaşkanınca''ya değiştirilmiştir.)', 44),
  ('652-khk-cld652-047-lc8d', '652-khk', 'Ek Madde 5''e göre zorunlu öğretim kapsamında öğrenim gören öğrenciler, 6114 sayılı Kanunun hangi maddesinin Bakanlık sınavlarına uygulanmasından istisna tutulmuştur?', '["9 uncu madde","8 inci madde","10 uncu madde","7 nci madde","6 ncı madde"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: 10 uncu madde. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 5/1''in metnine göre 6114 sayılı Kanunun 7 nci maddesinin 2-5 inci, 8 inci maddesinin 4 üncü ve 9 uncu maddesinin 1,2,3,4,5,7,8 inci fıkraları ile ''zorunlu öğretim kapsamında öğrenim gören öğrenciler hariç 10 uncu maddesi hükümleri'' Bakanlıkça yapılan merkezi sınavlar hakkında da uygulanır; istisna tutulan madde 10 uncu maddedir.', 47),
  ('652-khk-cld652-048-2m4b', '652-khk', 'Ek Madde 5/2''ye göre, 6114 sayılı Kanunun 9 uncu maddesinin üçüncü fıkrasındaki Ölçme, Seçme ve Yerleştirme Merkezi Başkanlığına ait yetkiler, Bakanlık sınavlarında kim tarafından kullanılır?', '["Talim ve Terbiye Kurulu Başkanlığı","Bakanlık Müsteşarı","İl Millî Eğitim Müdürlüğü","Ölçme, Değerlendirme ve Sınav Hizmetleri Genel Müdürlüğü","Bakanlık"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Bakanlık. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 5/2''ye göre 6114 sayılı Kanunun 9 uncu maddesinin üçüncü fıkrasındaki ÖSYM Başkanlığına ait yetkiler, Bakanlıkça yapılan merkezi sınavlarda Bakanlık tarafından kullanılır.', 48),
  ('652-khk-cld652-050-ikly', '652-khk', 'Ek Madde 5/2''ye göre 6114 sayılı Kanunun 10 uncu maddesinin sekizinci fıkrasındaki yetkiler, Bakanlık sınavlarında kim tarafından kullanılır?', '["Bakan","İl Millî Eğitim Müdürü","Bakanlık Müsteşarı","Talim ve Terbiye Kurulu Başkanı","Ölçme, Değerlendirme ve Sınav Hizmetleri Genel Müdürü"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Bakanlık Müsteşarı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 5/2''nin son kısmına göre 6114 sayılı Kanunun 10 uncu maddesinin sekizinci fıkrasındaki yetkiler Bakanlık Müsteşarı tarafından kullanılır.', 50),
  ('652-khk-cld652-051-r180', '652-khk', 'Ek Madde 5/2''ye göre Bakanlıkça yapılan merkezi sınavlara ilişkin olarak 6114 sayılı Kanunda Ölçme, Seçme ve Yerleştirme Merkezi Başkanlığına yapılan atıflar kime yapılmış sayılır?', '["Millî Eğitim Bakanına","Ölçme, Değerlendirme ve Sınav Hizmetleri Genel Müdürlüğüne","Bakanlığa","Talim ve Terbiye Kurulu Başkanlığına","Cumhurbaşkanlığına"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: Bakanlığa. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Ek Madde 5/2''nin ilk cümlesine göre Bakanlık tarafından yapılan merkezi sınavlara ilişkin olarak ÖSYM Başkanlığına yapılan atıflar Bakanlığa yapılmış sayılır.', 51),
  ('652-khk-cld652-053-wlq3', '652-khk', '652 sayılı KHK''de bugün yürürlükte olan tek geçici madde hangisidir?', '["Geçici Madde 16","Geçici Madde 9","Geçici Madde 10","Geçici Madde 11","Geçici Madde 15"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: Geçici Madde 16. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. 652 sayılı KHK''nin Geçici Madde 1 ilâ 15''i 2/7/2018 tarihli ve 703 sayılı KHK ile mülga edilmiştir; yalnızca 27/6/2019 tarihli ve 7180 sayılı Kanunun 18 inci maddesiyle eklenen Geçici Madde 16 yürürlüktedir.', 53),
  ('652-khk-cld652-054-50s3', '652-khk', 'Geçici Madde 16''ya göre, maddenin yürürlüğe girdiği tarihten önce alınmış sürekli veya süreli engelli sağlık kurulu raporu bulunan bireyler, rapor süreleri bitene kadar hangi madde kapsamında destek eğitimi almaya devam ederler?', '["13 üncü madde","Ek Madde 5","23 üncü madde","43 üncü madde","31 inci madde"]'::jsonb, 3, '[652 Sayılı KHK] Doğru cevap: 43 üncü madde. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Geçici Madde 16/1''e göre bu maddenin yürürlüğe girdiği tarihten önce alınmış engelli sağlık kurulu raporları bulunan bireylerden sürekli raporu bulunanlar ile süreli raporu bulunup rapor süresi devam edenler, rapor süreleri bitene kadar 43 üncü madde kapsamında destek eğitimi almaya devam ederler.', 54),
  ('652-khk-cld652-055-lu74', '652-khk', '652 sayılı KHK ne zaman yürürlüğe girmiştir?', '["Kabul tarihinde","Yayımından bir yıl sonra","1/1/2012 tarihinde","Yayımından altı ay sonra","Yayımı tarihinde"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Yayımı tarihinde. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 45''e göre ''Bu Kanun Hükmünde Kararname yayımı tarihinde yürürlüğe girer.''; KHK 14/9/2011 tarihli ve 28054 sayılı Resmî Gazete''de yayımlanmıştır.', 55),
  ('652-khk-cld652-056-2h77', '652-khk', '652 sayılı KHK hükümlerini kim yürütür?', '["TBMM Başkanlığı","Millî Eğitim Bakanı","Bakanlar Kurulu ve Millî Eğitim Bakanı birlikte","Cumhurbaşkanı tek başına","Bakanlar Kurulu"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: Bakanlar Kurulu. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Madde 46''ya göre ''Bu Kanun Hükmünde Kararname hükümlerini Bakanlar Kurulu yürütür.''', 56),
  ('652-khk-cld652-057-rgno', '652-khk', '652 sayılı KHK''nin 42 nci maddesi (sözleşmeli personel ve ek ödeme), Anayasa Mahkemesinin hangi kararıyla iptal edilmiştir?', '["13/7/2015 tarihli ve E:2014/88, K:2015/68 sayılı Kararı","6/2/2013 tarihli ve E:2011/123, K:2013/26 sayılı Kararı","27/12/2012 tarihli ve E:2011/139, K:2012/205 sayılı Kararı","7/12/2023 tarihli ve E:2018/117, K:2023/212 sayılı Kararı","28/9/2023 tarihli ve E:2023/59, K:2023/164 sayılı Kararı"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: 27/12/2012 tarihli ve E:2011/139, K:2012/205 sayılı Kararı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Değişiklik tablosuna göre madde 42, Anayasa Mahkemesinin 27/12/2012 tarihli ve E:2011/139, K:2012/205 sayılı Kararı ile iptal edilmiş; iptal 10/10/2013 tarihinde yürürlüğe girmiştir. Ayrıca madde, 11/10/2011 tarihli ve 666 sayılı KHK''nin 1 inci maddesiyle de mülga edilmiştir.', 57),
  ('652-khk-cld652-058-af3v', '652-khk', '652 sayılı KHK''nin 37 nci maddesi ile Geçici Madde 5''i, Anayasa Mahkemesinin hangi tarihli kararıyla ve ne zaman yürürlüğe girecek şekilde iptal edilmiştir?', '["7/12/2023 tarihli Kararı; 4/6/2025 tarihinde yürürlüğe girmiştir","6/2/2013 tarihli ve E:2011/123, K:2013/26 sayılı Kararı; 31/12/2013 tarihinde yürürlüğe girmiştir","28/9/2023 tarihli Kararı; 23/11/2023 tarihinde yürürlüğe girmiştir","13/7/2015 tarihli Kararı; 24/7/2015 tarihinde yürürlüğe girmiştir","27/12/2012 tarihli Kararı; 10/10/2013 tarihinde yürürlüğe girmiştir"]'::jsonb, 1, '[652 Sayılı KHK] Doğru cevap: 6/2/2013 tarihli ve E:2011/123, K:2013/26 sayılı Kararı; 31/12/2013 tarihinde yürürlüğe girmiştir. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Değişiklik tablosuna göre madde 37 ve Geçici Madde 5, Anayasa Mahkemesinin 6/2/2013 tarihli ve E:2011/123, K:2013/26 sayılı Kararı ile iptal edilmiş; bu iptal 31/12/2013 tarihinde yürürlüğe girmiştir.', 58),
  ('652-khk-cld652-059-08lb', '652-khk', '652 sayılı KHK''nin Geçici Madde 10''u, Anayasa Mahkemesinin hangi kararıyla iptal edilmiştir?', '["27/12/2012 tarihli ve E:2011/139, K:2012/205 sayılı Kararı","10/10/2024 tarihli ve 7528 sayılı Kanun","6/2/2013 tarihli ve E:2011/123, K:2013/26 sayılı Kararı","7/12/2023 tarihli ve E:2018/117, K:2023/212 sayılı Kararı","13/7/2015 tarihli ve E:2014/88, K:2015/68 sayılı Kararı"]'::jsonb, 4, '[652 Sayılı KHK] Doğru cevap: 13/7/2015 tarihli ve E:2014/88, K:2015/68 sayılı Kararı. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Değişiklik tablosuna göre Geçici Madde 10, Anayasa Mahkemesinin 13/7/2015 tarihli ve E:2014/88, K:2015/68 sayılı Kararı ile iptal edilmiş; bu iptal 24/7/2015 tarihinde yürürlüğe girmiştir.', 59),
  ('652-khk-cld652-062-9nsr', '652-khk', '20/11/2017 tarihli ve 696 sayılı KHK ile eklenen Ek Madde 6, Geçici Madde 13 ve Geçici Madde 14 hangi kanunla aynen kabul edilmiştir?', '["10/10/2024 tarihli ve 7528 sayılı Kanun","27/3/2018 tarihli ve 7103 sayılı Kanun","1/2/2018 tarihli ve 7079 sayılı Kanun","2/7/2018 tarihli ve 703 sayılı KHK","8/3/2018 tarihli ve 7078 sayılı Kanun"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: 1/2/2018 tarihli ve 7079 sayılı Kanun. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Değişiklik tablosuna göre 696 sayılı KHK ile eklenen Ek Madde 6, Geçici Madde 13 ve Geçici Madde 14, 1/2/2018 tarihli ve 7079 sayılı Kanunla aynen kabul edilmiş; her ikisi de 8/3/2018 tarihinde yürürlüğe girmiştir. Bu hükümlerin tamamı daha sonra 703 sayılı KHK ile mülga edilmiştir.', 62),
  ('652-khk-cld652-064-g1kg', '652-khk', '10/10/2024 tarihli ve 7528 sayılı Kanun, 652 sayılı KHK''nin hangi maddelerinde değişiklik yapmıştır?', '["31, 37 ve Ek Madde 4","42 ve Geçici Madde 10","13 ve 23","43 ve Geçici Madde 16","Ek Madde 1 ve Ek Madde 5"]'::jsonb, 0, '[652 Sayılı KHK] Doğru cevap: 31, 37 ve Ek Madde 4. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Değişiklik tablosuna göre 7528 sayılı Kanun, 652 sayılı KHK''nin 31, 37 nci maddeleri ile Ek Madde 4''te değişiklik yapmış olup 18/10/2024 tarihinde yürürlüğe girmiştir.', 64),
  ('652-khk-cld652-068-qea0', '652-khk', 'Madde 12 (Hayat Boyu Öğrenme Genel Müdürlüğü), 703 sayılı KHK ile mülga edilmeden önce en son hangi düzenlemeyle değiştirilmişti?', '["1/3/2014 tarihli ve 6528 sayılı Kanun","2/12/2016 tarihli ve 6764 sayılı Kanun","9/2/2017 tarihli ve 687 sayılı KHK","8/3/2018 tarihli ve 7076 sayılı Kanun","20/11/2017 tarihli ve 696 sayılı KHK"]'::jsonb, 2, '[652 Sayılı KHK] Doğru cevap: 9/2/2017 tarihli ve 687 sayılı KHK. Dayanak: 652 sayılı Özel Barınma Hizmeti Veren Kurumlar ve Bazı Düzenlemeler Hakkında Kanun Hükmünde Kararname. Değişiklik tablosuna göre madde 12, sırasıyla 6764 sayılı Kanun (9/12/2016), KHK/687 (9/2/2017) ve 7076 sayılı Kanun (8/3/2018) ile değişikliğe uğramış, en nihayetinde 703 sayılı KHK ile mülga edilmiştir. KHK/687 ile yapılan değişiklik 9/2/2017 tarihinde yürürlüğe girmiştir.', 68),
